#!/usr/bin/env bash
set -euo pipefail

if [[ $# -lt 3 || $# -gt 4 ]]; then
  echo "Usage: $0 <version> <core-url> <core-checksum> [output]" >&2
  exit 1
fi

version="$1"
core_url="$2"
core_checksum="$3"
output="${4:-Package.swift}"

if [[ ! "$core_checksum" =~ ^[0-9a-f]{64}$ ]]; then
  echo "Invalid checksum '$core_checksum': expected 64 lowercase hex characters" >&2
  exit 1
fi

cat > "$output" <<EOF
// swift-tools-version: 5.9
// Generated by .github/scripts/generate-package-swift.sh for Peekniko ${version}. Do not edit.
import PackageDescription

let package = Package(
    name: "PeeknikoKit",
    platforms: [.iOS(.v17)],
    products: [
        // The inspector. Link it into debug/internal app targets.
        .library(name: "PeeknikoKit", targets: ["PeeknikoKit"]),
        // Same API that does nothing. Link it into production app targets instead.
        .library(name: "PeeknikoKitNoop", targets: ["PeeknikoCoreNoop"]),
    ],
    targets: [
        // Binary targets can't declare linker settings, so this wrapper links SQLite
        // for the SQLDelight storage bundled in PeeknikoCore.
        .target(
            name: "PeeknikoKit",
            dependencies: ["PeeknikoCore"],
            path: "library-ios/swift",
            linkerSettings: [.linkedLibrary("sqlite3")]
        ),
        .binaryTarget(
            name: "PeeknikoCore",
            url: "${core_url}",
            checksum: "${core_checksum}"
        ),
        .target(
            name: "PeeknikoCoreNoop",
            path: "library-ios/noop"
        ),
    ]
)
EOF

echo "Wrote $output for ${version}"
